import { test as setup, expect } from '@playwright/test';

const authFile = '.auth/user.json';

// detected scheme: bearer (collections/orders.postman_collection.json: Authorization header)
setup('authenticate', async ({ page, request }) => {
  const token = process.env.AUTH_TOKEN ?? '';
  await page.context().setExtraHTTPHeaders({ Authorization: `Bearer ${token}` });
  await page.context().storageState({ path: authFile });
});

import { test, expect } from '@playwright/test';

test.describe('Orders API', () => {
  // traces: REQ-201 — The orders list endpoint returns 200 for an authenticated caller
  test('List orders', async ({ request }) => {
    const response = await request.get('https://api.example.com/orders');
    expect(response.status()).toBe(200);
  });
  // traces: REQ-202 — Creating an order returns 201
  test('Create order', async ({ request }) => {
    const response = await request.post('https://api.example.com/orders', { data: {} });
    expect(response.status()).toBe(201);
  });
  // traces: REQ-203 — A single order can be fetched by id
  test('Get order by id', async ({ request }) => {
    const response = await request.get('https://api.example.com/orders/42');
    expect(response.status()).toBe(200);
  });
});

