import { test, expect } from '@playwright/test';

test.describe('Account settings', () => {
  // traces: REQ-101 — A user can update their display name
  // source: cypress/e2e/account-settings.cy.js :: updates the display name
  test('Updates the display name', async ({ page }) => {
    await page.locator('#display-name').fill('Ada Lovelace');
    await page.locator('[data-cy=save]').click();
    await expect(page.locator('.toast')).toHaveText('Saved');
  });

  // traces: REQ-102 — An empty display name is rejected
  // source: cypress/e2e/account-settings.cy.js :: rejects an empty display name
  test('Rejects an empty display name', async ({ page }) => {
    await page.locator('[data-cy=save]').click();
    await expect(page.locator('.field-error')).toBeVisible();
  });

  // traces: REQ-103 — A user can change their notification preference
  // source: cypress/e2e/account-settings.cy.js :: changes the notification preference
  test('Changes the notification preference', async ({ page }) => {
    await page.locator('#notifications').selectOption('Weekly digest');
    await page.locator('[data-cy=save]').click();
    await expect(page.locator('.toast')).toHaveText('Saved');
  });

});

