import { test, expect } from '@playwright/test';

test.describe('Login Test', () => {
  // traces: REQ-001 — A shopper can log in with valid credentials
  // source: src/test/java/com/acme/tests/LoginTest.java :: userCanLogInWithValidCredentials
  test('User Can Log In With Valid Credentials', async ({ page }) => {
    await page.goto('https://shop.example.com/login');
    await page.locator('#username').fill('standard_user');
    await page.locator('#password').fill(process.env.PASSWORD ?? '');
    await page.locator('button[type=\'submit\']').click();
    // auto-waiting replaces an explicit 2000ms sleep
    await expect(page).toHaveTitle('Products');
    await expect(page.locator('.inventory_list')).toBeVisible();
  });

  // traces: REQ-002 — An invalid password shows an inline error message
  // source: src/test/java/com/acme/tests/LoginTest.java :: invalidPasswordShowsError
  test('Invalid Password Shows Error', async ({ page }) => {
    await page.goto('https://shop.example.com/login');
    await page.locator('#username').fill('standard_user');
    await page.locator('#password').fill(process.env.PASSWORD ?? '');
    await page.locator('button[type=\'submit\']').click();
    await expect(page.locator('[data-test=\'error\']')).toHaveText('Username and password do not match any user in this service');
  });

  // traces: REQ-003 — A locked out user is rejected with an error
  // source: src/test/java/com/acme/tests/LoginTest.java :: lockedOutUserIsRejected
  test('Locked Out User Is Rejected', async ({ page }) => {
    await page.goto('https://shop.example.com/login');
    await page.locator('#username').fill('locked_out_user');
    await page.locator('#password').fill(process.env.PASSWORD ?? '');
    await page.locator('xpath=//button[@type=\'submit\']').click();
    await expect(page.locator('[data-test=\'error\']')).toBeVisible();
  });

});

import { test, expect } from '@playwright/test';

test.describe('Checkout Test', () => {
  // traces: REQ-004 — A shopper can complete checkout and see the order total
  // source: src/test/java/com/acme/tests/CheckoutTest.java :: userCanCompleteCheckout
  test('User Can Complete Checkout', async ({ page }) => {
    await page.goto('https://shop.example.com/cart');
    await page.locator('#checkout').click();
    await page.locator('#first-name').fill('Ada');
    await page.locator('#last-name').fill('Lovelace');
    await page.locator('#postal-code').fill('SW1A 1AA');
    await page.locator('#shipping').selectOption('Next day');
    await page.locator('#continue').click();
    await expect(page.locator('.summary_total_label')).toHaveText('Total: $49.99');
  });

  // traces: REQ-005 — The cart badge reflects the number of items added
  // source: src/test/java/com/acme/tests/CheckoutTest.java :: cartBadgeReflectsItemCount
  test('Cart Badge Reflects Item Count', async ({ page }) => {
    await page.goto('https://shop.example.com/inventory');
    await page.locator('[data-test=\'add-to-cart-backpack\']').click();
    await expect(page.locator('.shopping_cart_badge')).toHaveText('1');
  });

});

